body.t-watercolor .bg-fx {
  background:
    radial-gradient(ellipse 340px 260px at 12% 18%, rgba(91,142,196,.13), transparent 70%),
    radial-gradient(ellipse 400px 300px at 88% 30%, rgba(212,132,124,.11), transparent 70%),
    radial-gradient(ellipse 380px 280px at 20% 82%, rgba(168,184,122,.12), transparent 70%),
    radial-gradient(ellipse 320px 260px at 78% 78%, rgba(220,190,120,.12), transparent 70%);
  filter: blur(28px);
}
body.t-watercolor .hero h1 { font-style: italic; letter-spacing: -1px; color: #3c3a36; }
body.t-watercolor .tagline { font-style: italic; }
body.t-watercolor .section-title { font-style: italic; }
body.t-watercolor .section-title::after { content: ""; display: block; width: 130px; height: 7px; margin-top: 8px; background: linear-gradient(90deg, rgba(91,142,196,.5), rgba(212,132,124,.3), transparent); border-radius: 99px; filter: blur(1px); }
body.t-watercolor .section-tag { border: 2px solid rgba(91,142,196,.35); background: rgba(255,254,250,.7); border-radius: 14px 4px 16px 6px; }
body.t-watercolor .card { border: 2px solid rgba(91,142,196,.3); border-radius: 22px 8px 24px 10px; }
body.t-watercolor .card:nth-child(even) { border-radius: 10px 24px 8px 22px; border-color: rgba(212,132,124,.3); }
body.t-watercolor .card:nth-child(even):hover { border-color: #d4847c; }
body.t-watercolor .card.featured { border-color: #5b8ec4; border-width: 2.5px; }
body.t-watercolor .card.featured::before { background: #d4847c; border-radius: 99px 0 0 99px; }
